import java.io.*;
import java.net.*;
import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String customFilter = req.getParameter("filter");
        String format = req.getParameter("format");

        // Validate format parameter
        if (format == null || (!format.equals("csv") && !format.equals("json"))) {
            format = "json";
        }

        // Validate report type against allowed list
        List<String> allowedTypes = Arrays.asList("sales", "inventory", "users", "audit");
        if (reportType == null || !allowedTypes.contains(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Build query - dates are parameterized but filter is dynamic
        String baseQuery = "SELECT * FROM reports WHERE report_type = ? AND created_at BETWEEN ? AND ?";

        // Custom filter allows advanced users to add conditions
        // We strip obvious dangerous keywords as a defense measure
        if (customFilter != null && !customFilter.isEmpty()) {
            customFilter = customFilter.replaceAll("(?i)(DROP|ALTER|TRUNCATE|CREATE|GRANT)", "");
            customFilter = customFilter.replace(";", "");
            baseQuery += " AND (" + customFilter + ")";
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(baseQuery)) {

            stmt.setString(1, reportType);
            stmt.setString(2, startDate != null ? startDate : "2020-01-01");
            stmt.setString(3, endDate != null ? endDate : "2099-12-31");

            ResultSet rs = stmt.executeQuery();
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();

            resp.setContentType(format.equals("csv") ? "text/csv" : "application/json");
            PrintWriter out = resp.getWriter();

            if (format.equals("json")) {
                out.print("[\n");
                boolean first = true;
                while (rs.next()) {
                    if (!first) out.print(",\n");
                    out.print("  {");
                    for (int i = 1; i <= cols; i++) {
                        if (i > 1) out.print(", ");
                        out.print("\"" + meta.getColumnName(i) + "\": ");
                        out.print("\"" + escapeJson(rs.getString(i)) + "\"");
                    }
                    out.print("}");
                    first = false;
                }
                out.print("\n]");
            } else {
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) out.print(",");
                    out.print(meta.getColumnName(i));
                }
                out.println();
                while (rs.next()) {
                    for (int i = 1; i <= cols; i++) {
                        if (i > 1) out.print(",");
                        out.print(escapeCsv(rs.getString(i)));
                    }
                    out.println();
                }
            }
        } catch (SQLException e) {
            resp.sendError(500, "Query failed: " + e.getMessage());
        }
    }

    private String escapeJson(String val) {
        if (val == null) return "null";
        return val.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }

    private String escapeCsv(String val) {
        if (val == null) return "";
        if (val.contains(",") || val.contains("\"") || val.contains("\n")) {
            return "\"" + val.replace("\"", "\"\"") + "\"";
        }
        return val;
    }
}
